"""One-purpose actual control diagnostic; not an M1 qualification retry.
Reuse the reviewed isolated server/ownership/finalization procedure, changing only
its native task prompt and transient HTTP-error observation. No runtime changes.
"""
import ast
import hashlib
import json
import re
from pathlib import Path
from server_utils import parse_transactions as original_parse

original = Path(__file__).with_name('applications.py')
source = original.read_text()
probe = '''This is a TextEdit control diagnostic, NOT the M1 multi-window task. Existing Appium/Selenium imports are available; use importlib.metadata and sys for versions. Missing packaging/pip is NOT incompatibility and does NOT authorize installs, downloads, bootstrap code or user-site changes. Do not fetch package registries or websites. Create exactly one fresh actual Mac2/TextEdit session against the provided owned endpoint. Query the initial windows without printing titles or content; unexpected personal-document reopening means stop. Do NOT repeat Cmd+O or menu opening: those failed in the prior observed run. Try the alternative official macos:deepLink extension with the exact source file URI (source.as_uri()) and bundleId com.apple.TextEdit. Query the resulting window identity and fixture-only content if the action succeeds. On any failure, preserve actual status/kernelState; inspect the exception's actual msg and make a relevant small live query, but do NOT blindly retry or create another session. Return only bounded diagnostic booleans plus safe driver error classification; external verifier observes actual HTTP error responses. Whether the task worked or failed, restore only the newly owned task windows/app and original foreground before quit, delete the owned session and preserve the preexisting server. Canonical taskOutcome should be completed only if direct-open and synthetic identity observation succeeded, otherwise blocked; restoration/session/server are separate. No permission/signing/global setting changes, no personal documents, no screenshots/page source. Follow common ownership and cleanup rules.'''
probe = probe.replace('source.as_uri()', 'the primary target URI already provided in setup')

class DiagnosticVariant(ast.NodeTransformer):
    def visit_ImportFrom(self,node):
        if node.module == 'server_utils':
            node.names = [name for name in node.names if name.name != 'parse_transactions']
        return node
    def visit_Assign(self,node):
        if any(isinstance(target,ast.Name) and target.id == 'tasks' for target in node.targets):
            node.value = ast.Dict(keys=[ast.Constant('M1')],values=[ast.Constant(probe)])
        return self.generic_visit(node)

def parse_with_diagnostics(path):
    transactions = original_parse(path) or []
    observed = []
    for transaction in transactions:
        if transaction.get('status') is None or transaction['status'] < 400:
            continue
        for response in transaction.get('proxy',[]) + transaction.get('responding',[]):
            value = response.get('value') if isinstance(response,dict) else None
            if not isinstance(value,dict):
                continue
            message = value.get('message')
            if not isinstance(message,str):
                continue
            safe = re.sub(r'[0-9a-fA-F]{8}-[0-9a-fA-F-]{27,}', '$SESSION', message)
            safe = re.sub(r'/Users/[^/\s]+', '$HOME', safe)
            observed.append({'httpStatus':transaction['status'],'error':str(value.get('error'))[:80],'message':safe[:1600],'messageSha256':hashlib.sha256(message.encode()).hexdigest()})
    internal_errors = []
    for line in path.read_text(errors='replace').splitlines():
        if 'Encountered internal error running command' in line:
            safe = re.sub(r'[0-9a-fA-F]{8}-[0-9a-fA-F-]{27,}', '$SESSION', line)
            safe = re.sub(r'/Users/[^/\s]+', '$HOME', safe)
            internal_errors.append(safe[:1600])
    # Transient diagnostic only; not copied into the retained scenario artifact.
    if observed or internal_errors:
        print(json.dumps({'diagnosticVariantNotM1':True,'httpErrors':observed[:8],'internalErrors':internal_errors[:8]}),flush=True)
    return transactions

tree = DiagnosticVariant().visit(ast.parse(source))
ast.fix_missing_locations(tree)
namespace = dict(globals(),parse_transactions=parse_with_diagnostics)
exec(compile(tree,str(original),'exec'),namespace)
